-- KO-225 group 2 missing body_id translation batch 6

update public.content_variants set body = $json${"text":"Rina has 3 PayLater bills at once: electronics, clothes and cosmetics. Total monthly installments IDR 700,000. He had difficulty remembering each due date and ended up paying one of them late. The fines piled up and made him regret buying things that weren't really important."}$json$::jsonb, body_id = $json${"text":"Rina punya 3 tagihan PayLater sekaligus: elektronik, pakaian, dan kosmetik. Total cicilan bulanan Rp 700.000. Ia kesulitan mengingat jatuh tempo masing-masing dan akhirnya telat bayar salah satu. Denda menumpuk dan membuatnya menyesal membeli barang yang tidak terlalu penting."}$json$::jsonb where id = '71a1145d-6074-4bd6-ae20-1f12a9f81430';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"The buzz on social media is a great reason to buy crypto.","difficulty":"beginner","explanation":"Nothing is certain in financial markets. Claims that it will definitely rise are often used to fuel FOMO and fraud."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Omongan pasti naik di media sosial adalah alasan yang bagus untuk membeli kripto.","difficulty":"beginner","explanation":"Tidak ada yang pasti di pasar keuangan. Klaim pasti naik sering digunakan untuk memicu FOMO dan penipuan."}$json$::jsonb where id = '73aab87d-06d7-41d4-a80e-f3043059a59e';
update public.content_variants set body = $json${"type":"true_false","answer":true,"question":"PayLater is safest if used for planned needs that fit the budget.","difficulty":"beginner","explanation":"PayLater should be a planned payment tool, not a trigger for impulse purchases."}$json$::jsonb, body_id = $json${"type":"true_false","answer":true,"question":"PayLater paling aman jika digunakan untuk kebutuhan terencana yang sesuai anggaran.","difficulty":"beginner","explanation":"PayLater sebaiknya menjadi alat pembayaran yang sudah direncanakan, bukan pemicu pembelian impulsif."}$json$::jsonb where id = '78a29907-903b-4b56-a7e2-4032dd071e91';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Productive investments usually generate wealth quickly like crypto trading.","difficulty":"beginner","explanation":"Productive investments usually build wealth slowly through interest, dividends and economic growth."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Investasi produktif biasanya menghasilkan kekayaan dengan cepat seperti trading kripto.","difficulty":"beginner","explanation":"Investasi produktif biasanya membangun kekayaan secara perlahan melalui bunga, dividen, dan pertumbuhan ekonomi."}$json$::jsonb where id = '7acaa60d-4b59-4a1a-85db-aab7f031d86e';
update public.content_variants set body = $json${"text":"Dina opened Shopee and saw a skincare flash sale of IDR 450,000 with a PayLater offer. He didn't plan the purchase. Before checking out, he checked his budget and realized he had run out of concert tickets. He closed the application and saved the skincare for next month if he still wanted it."}$json$::jsonb, body_id = $json${"text":"Dina membuka Shopee dan melihat flash sale skincare Rp 450.000 dengan tawaran PayLater. Ia tidak merencanakan pembelian itu. Sebelum checkout, ia mengecek anggaran keinginannya dan menyadari sudah habus untuk tiket konser. Ia menutup aplikasi dan menyimpan skincare itu untuk bulan depan jika masih ingin."}$json$::jsonb where id = '7b8fbfdf-6c5c-4745-b9b7-bf7188c68c3b';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Borrow 36% interest","options":["Borrow 36% interest","Brother's debt","Both at once","Depends on who charges harder"],"question":"Which debt should Raka pay off first: a loan with 36% interest per year or his brother's debt without interest?","difficulty":"beginner","explanation":"Debt with the highest interest rates damages finances the quickest, so it takes precedence in the avalanche method."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Pinjol bunga 36%","options":["Pinjol bunga 36%","Utang kakak","Keduanya sekaligus","Tergantung siapa yang menagih lebih keras"],"question":"Utang mana yang harus Raka lunasi pertama: pinjol bunga 36% per tahun atau utang kakak tanpa bunga?","difficulty":"beginner","explanation":"Utang dengan bunga tertinggi merusak keuangan paling cepat, jadi didahulukan dalam metode avalanche."}$json$::jsonb where id = '7d7a7807-625b-47b7-8567-553c15eb5609';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Pay bills in full and on time","options":["Pay bills in full and on time","Pay the minimum every month","Missing due date occasionally","Use the entire limit every month"],"question":"Which habits build a good credit record?","difficulty":"beginner","explanation":"Full and on-time payments are recorded in SLIK as a positive credit history."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Membayar tagihan penuh dan tepat waktu","options":["Membayar tagihan penuh dan tepat waktu","Membayar minimum setiap bulan","Melewati jatuh tempo sesekali","Memakai seluruh limit setiap bulan"],"question":"Kebiasaan mana yang membangun rekam kredit bagus?","difficulty":"beginner","explanation":"Pembayaran penuh dan tepat waktu tercatat di SLIK sebagai riwayat kredit positif."}$json$::jsonb where id = '7da09e85-1e36-4bfb-b6b3-e63e548a9f3b';
update public.content_variants set body = $json${"text":"Every payday, Andi arranges a full auto-debit for his credit card bill. He uses the card only for monthly shopping and gets cashback of IDR 100 thousand per month. Because credit cards never pay interest, they actually save on expenses."}$json$::jsonb, body_id = $json${"text":"Setiap gajian, Andi mengatur autodebet penuh untuk tagihan kartu kreditnya. Ia memakai kartu hanya untuk belanja bulanan dan mendapat cashback Rp 100 ribu per bulan. Karena tidak pernah membayar bunga, kartu kredit justru menghemat pengeluarannya."}$json$::jsonb where id = '7ecf1d4b-698e-429a-a968-535b929a427c';
update public.content_variants set body = $json${"type":"true_false","answer":true,"question":"Keeping a record of the date and price of each crypto transaction helps when calculating taxes.","difficulty":"beginner","explanation":"Neat transaction records make tax reporting easier and avoid problems in the future."}$json$::jsonb, body_id = $json${"type":"true_false","answer":true,"question":"Menyimpan catatan tanggal dan harga setiap transaksi kripto membantu saat menghitung pajak.","difficulty":"beginner","explanation":"Catatan transaksi yang rapi memudahkan pelaporan pajak dan menghindari masalah di kemudian hari."}$json$::jsonb where id = '81fc5287-c9f7-4a11-8802-4bf2f11b7150';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Verify user identity","options":["Verify user identity","Discount code for trading","Types of crypto wallets","Investment strategy"],"question":"What is KYC in the context of crypto?","difficulty":"beginner","explanation":"KYC (Know Your Customer) is the process by which an exchange verifies a user's identity to prevent fraud and money laundering."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Verifikasi identitas pengguna","options":["Verifikasi identitas pengguna","Kode diskon untuk trading","Jenis dompet kripto","Strategi investasi"],"question":"Apa itu KYC dalam konteks kripto?","difficulty":"beginner","explanation":"KYC (Know Your Customer) adalah proses bursa memverifikasi identitas pengguna untuk mencegah penipuan dan pencucian uang."}$json$::jsonb where id = '83cf6386-d712-428a-8b7d-86a6ccfbe4e7';

